internal class GUPPriceEngineConditionValueObject
{
    // Key = classId of GUPIPricingAttributeProvider, value = class object.
    private static Map attributeProviderClassIdMap = new Map(Types::Int64, Types::AnyType);

    // Key = classId of GUPIPricingAttribute, value = class object.
    private static Map attributeClassIdMap = new Map(Types::Int64, Types::AnyType);

    boolean ecoResAttribute = false;
    str conditionValue;
    int attributePriority;
    GUPPricingAttributeLink attributeLink;
    GUPIPricingAttribute pricingAttribute;
    GUPIPricingAttributeProvider attributeProvider;

}

Method.Source:
    public void new (str _conditionValue, GUPPricingAttributeLink _attributeLink)
    {
        this.conditionValue = _conditionValue;

        // Make a copy by the cursor.
        this.attributeLink = _attributeLink.data();

        this.loadPricingAttribute(_attributeLink);

        this.loadAttributePriority();
    }

    private void loadPricingAttribute(GUPPricingAttributeLink _attributeLink)
    {        
        // attribute from GUPIPricingAttribute.
        if (!this.attributeLink.AttributeProviderClassId)
        {
            if (!attributeClassIdMap.exists(this.attributeLink.PriceAttributeClassId))
            {
                DictClass dictClass = new DictClass(this.attributeLink.PriceAttributeClassId);
                pricingAttribute = dictClass.makeObject();
                attributeClassIdMap.add(this.attributeLink.PriceAttributeClassId, pricingAttribute);
            }
            else 
            {
                pricingAttribute = attributeClassIdMap.lookup(this.attributeLink.PriceAttributeClassId);
            }
            
        }
        // attribute from GUPIPricingAttributeProvider -- new instance for each condition value.
        else
        {
            this.loadAttributeProvider(this.attributeLink.AttributeProviderClassId);
            this.ecoResAttribute = true;

            pricingAttribute = new GUPPricingAttributeEcoResAttribute(
                this.attributeLink.AttributeName,
                this.attributeLink.TypeName,
                this.attributeProvider);
        }
    }

private void loadAttributeProvider(ClassId _attributeProviderClassId)
{
    if (attributeProviderClassIdMap.exists(_attributeProviderClassId))
    {
        this.attributeProvider = attributeProviderClassIdMap.lookup(_attributeProviderClassId);
    }
    else
    {
        DictClass dictClassProvider = new DictClass(_attributeProviderClassId);
        this.attributeProvider = dictClassProvider.makeObject();
        attributeProviderClassIdMap.add(_attributeProviderClassId, attributeProvider);
    }
}

    private void loadAttributePriority()
    {
        if (this.conditionValue == null || this.conditionValue == "")
        {
            this.attributePriority = 0;
        }
        
        // Store level for attribute's product category.
        if (classNum(GUPPricingAttributeEcoResProductCategoryCategory) == this.attributeLink.PriceAttributeClassId)
        {
            EcoResCategory ecoResCategory;

            select firstonly ecoResCategory
                where ecoResCategory.RecId == str2Int64(this.conditionValue);

            if (ecoResCategory)
            {
                this.attributePriority = ecoResCategory.Level;
            }

        }

        this.attributePriority = 1;
    }

/// <summary>
/// Return priority of this attribute. 
/// Normally return 1 for non-blank, 0 for blank value.
/// For attribute with "category hierarchy tree", return 0 for blank value, 1 for all, and larger value for deeper level.
/// </summary>
/// <returns>A non-negative integer shows priority. Larger is better.</returns>
public int parmAttributePriority()
{
    return this.attributePriority;
}
